# Settings for this section are in Study choices. # The screen is not run here. It is read. # # hzr_bootstrap() writes nothing until its final replicate and a full screen is # days of compute, so a run that dies near the end leaves nothing at all. The # companion runner exists to convert one all-or-nothing multi-day call into N # independently restartable ones. That file boundary is a DURABILITY boundary, # not tidiness, which is why this report reads chunks rather than producing # them. .boot_dir <- dirname(set_path("estimates", ".")) .chunk_files <- boot_chunk_files(.boot_dir, prefix = BOOT_PREFIX) .single_file <- set_path("estimates", paste0(BOOT_PREFIX, ".rds"))  if (length(.chunk_files)) {   # Pooling is checked, not assumed: boot_pool_chunks() refuses chunks that   # disagree on the dataset checksum, the entry/stay levels, the base   # parameters, the usable candidate counts, the engine version or the step   # cap, and refuses two chunks sharing a seed. Every one of those failures is   # silent on its own -- it shows up as a slightly different frequency, never   # as an error -- which is why the refusal belongs here rather than in a note.   .cfg <- study_config(start = .root)   .chunk_reads <- lapply(.chunk_files, hvtiRtemplates:::.read_bootstrap_artifact,                          role = "bootstrap-chunk", cfg = .cfg)   bag <- boot_pool_chunks(lapply(.chunk_reads, `[[`, "value"))   .chunk_lineage <- lapply(.chunk_reads, `[[`, "lineage")   .combined <- hvtiRtemplates:::.combine_handoff_lineage(.chunk_lineage)   .bootstrap_lineage <- .combined   .provenance_data <- .combined$data   .provenance_artifacts <- c(.combined$artifacts, lapply(.chunk_reads, `[[`, "record")) } else if (file.exists(.single_file)) {   .cfg <- study_config(start = .root)   .bag_read <- hvtiRtemplates:::.read_bootstrap_artifact(     .single_file, "bootstrap-bag", .cfg   )   bag <- .bag_read$value   .provenance_data <- .bag_read$lineage$data   .provenance_artifacts <- c(.bag_read$lineage$artifacts, list(.bag_read$record))   .bootstrap_lineage <- .bag_read$lineage } else {   stop("No bootstrap output found. This screen is a long job -- days, not ",        "minutes -- and is run from a companion script rather than inside this ",        "render, because the run writes nothing until its final replicate.
",        "Run your chunks first, then render this report.", call. = FALSE) } # This report reads a bag, not data. The runner recorded which rows it # screened, and that selection travels in the bag's lineage. A setting in Study # choices that differs from the runner's stops here. So does a bag with no # single selection: one written before the data contract, or one pooled from # chunks that were run on different rows. .bag_files <- basename(if (length(.chunk_files)) .chunk_files else .single_file) .bag_name <- if (length(.chunk_files)) {   paste0("the bootstrap bag pooled from ", length(.chunk_files), " chunks, ", .bag_files[[1L]], " to ",          .bag_files[[length(.bag_files)]]) } else {   paste("the bootstrap bag", .bag_files) } .sel <- hvtiRtemplates:::.read_upstream_job_data(   .cfg, .bootstrap_lineage, list(where = WHERE, id = ID, key = KEY), read = FALSE, source = .bag_name,   rerun = paste("Rerun the bootstrap runner, <subject>-<type>-bh-runner.R, as add_job() now writes it: it records",                 "the selection. Then render this report again.") )$selection knitr::kable(data.frame(step = c("ID", "KEY", "WHERE", "Rows"),                         value = c(.sel$id, paste(.sel$key, collapse = ", "),                                   if (length(.sel$where_shown)) paste(.sel$where_shown, collapse = "; ") else "none",                                   .sel$rows)),              col.names = c("Data", "")) # The contract: runners read their data with hvtiRtemplates::read_job_data(), whose # selection travels in the bag's lineage.  # A bag holds replicates and settings, never the rows the screen resampled. A # hazard bag is a list its runner writes by hand, so every file is searched: # a field, or a formula saved with its environment, can hold the runner's data. .bags <- if (length(.chunk_files)) lapply(.chunk_reads, `[[`, "value") else list(bag) for (.i in seq_along(.bags)) {   hvtiRtemplates:::.check_bag_identifiers(.bags[[.i]], .sel$id, paste("The bootstrap bag", .bag_files[[.i]])) } # A callout, not a table cell. A provisional report that cannot say so is the # failure being prevented, and it must survive someone receiving the .html # without knowing when it was made -- which a number buried in a provenance # table does not. .shortfall <- boot_shortfall(bag, EXPECT_CHUNKS, EXPECT_BOOT) if (!is.null(.shortfall)) {   cat("
::: {.callout-warning title="Provisional -- this pool is incomplete"}
")   cat(.shortfall, "
", sep = "")   cat(":::

") }

